CREATE POLICY "publico visualiza fotos produtos" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'produtos-midia');
CREATE POLICY "admin envia fotos produtos" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'produtos-midia' AND public.is_admin());
CREATE POLICY "admin altera fotos produtos" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'produtos-midia' AND public.is_admin()) WITH CHECK (bucket_id = 'produtos-midia' AND public.is_admin());
CREATE POLICY "admin remove fotos produtos" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'produtos-midia' AND public.is_admin());